import React, { useEffect, useState } from "react";
import { supabase } from "../supabaseClient";
import SlotCard from "../components/SlotCard";

const AdminDashboard = () => {
  const [slots, setSlots] = useState([]);

  useEffect(() => {
    fetchSlots();
    const interval = setInterval(fetchSlots, 2000);
    return () => clearInterval(interval);
  }, []);

  async function fetchSlots() {
    const { data, error } = await supabase
      .from("parking_slots")
      .select("*")
      .order("slot", { ascending: true });

    if (error) console.log(error);
    else setSlots(data);
  }

  const totalSlots = slots.length;
  const occupied = slots.filter((s) => s.status === "occupied").length;
  const vacant = totalSlots - occupied;

  return (
    <div className="dashboard-root">

      {/* Summary Section */}
      <div className="summary-row">
        <div className="summary-card blue">
          <div className="summary-title">Total Slots</div>
          <div className="summary-num">{totalSlots}</div>
        </div>

        <div className="summary-card red">
          <div className="summary-title">Occupied</div>
          <div className="summary-num">{occupied}</div>
        </div>

        <div className="summary-card green">
          <div className="summary-title">Vacant</div>
          <div className="summary-num">{vacant}</div>
        </div>
      </div>

      {/* Slots Section */}
      <div className="layout-title">Parking Slots</div>

      <div className="slots-grid">
        {slots.map((slot) => (
          <SlotCard key={slot.id} slot={slot} />
        ))}
      </div>

      <div className="small-footer">Smart Parking System • Admin Panel</div>

    </div>
  );
};

export default AdminDashboard;
